mapper.select:
SELECT oi.id, oi.order_no, oi.parent_type, oi.sub_type, oi.order_price, oi.reward_price, oi.goods_budget, oi.remark, oi.expect_time, oi.fetch_code, oi.order_status, oi.cancel_reason AS cancelReason, oi.create_time, sa.address AS startAddressText, ea.address AS endAddressText, ro.accept_time, ro.pick_time, ro.deliver_time, ro.finish_time, ro.rider_status, ro.service_fee, ro.cancel_reason AS riderCancelReason FROM order_info oi INNER JOIN tb_rider_order ro ON oi.order_no = ro.order_no LEFT JOIN user_address sa ON oi.start_address_id = sa.id LEFT JOIN user_address ea ON oi.end_address_id = ea.id WHERE oi.is_deleted = 0 AND ro.is_deleted = 0 AND ro.rider_user_id = #{dto.riderUserId} AND oi.order_status != 0
AND oi.order_status = #{dto.orderStatus}
AND oi.parent_type = #{dto.parentType}
AND oi.sub_type = #{dto.subType}
ORDER BY ${dto.sortField} ${dto.sortOrder}
ORDER BY ro.accept_time DESC

mapper.update:
UPDATE tb_rider_order
rider_order_no = #{riderOrderNo}, order_no = #{orderNo}, rider_user_id = #{riderUserId}, accept_time = #{acceptTime}, pick_time = #{pickTime}, deliver_time = #{deliverTime}, finish_time = #{finishTime}, rider_status = #{riderStatus}, service_fee = #{serviceFee}, cancel_reason = #{cancelReason}, pre_delivery_status = #{preDeliveryStatus}, update_time = #{updateTime}, is_deleted = #{isDeleted}
WHERE order_no = #{orderNo} AND is_deleted = 0
